const safe=(x,n=150)=>String(x??'').slice(0,n).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const clamp=(x,lo,hi)=>Math.max(lo,Math.min(hi,Number.isFinite(+x)?+x:lo));
