function openDb(){if(!('indexedDB' in window))return Promise.reject(new Error('no idb'));return new Promise((resolve,reject)=>{const req=indexedDB.open('tinglan-db',2);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv');if(!db.objectStoreNames.contains('logs'))db.createObjectStore('logs',{keyPath:'id'});if(!db.objectStoreNames.contains('sessions'))db.createObjectStore('sessions',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function idbGetKey(db,key){return new Promise((resolve,reject)=>{const req=db.transaction('kv','readonly').objectStore('kv').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function idbGetAll(db,store){return new Promise((resolve,reject)=>{const req=db.transaction(store,'readonly').objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}
function idbPut(db,store,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function idbDelete(db,store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function idbDeleteKey(db,key){return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function idbReplace(db,nextLogs,nextSessions){return new Promise((resolve,reject)=>{const tx=db.transaction(['logs','sessions'],'readwrite');tx.objectStore('logs').clear();tx.objectStore('sessions').clear();for(const x of nextLogs)tx.objectStore('logs').put(x);for(const x of nextSessions)tx.objectStore('sessions').put(x);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function normalizeRecord(store,entry){const item=store==='logs'?sanitizeLog(entry):sanitizeSession(entry);return item?{...item,id:item.id||uid()}:null}
function persist(){if(!booted)return;const payload={version:4,app:APP_VERSION,settings,profiles,favorites,person};if(!idbOk){payload.logs=logs.slice(-500);payload.sessions=sessions.slice(-1000)}else payload.logsIn='idb';try{localStorage.setItem(KEY,JSON.stringify(payload))}catch{notify('存储空间不足，请导出备份')}}
function persistNow(){persist()}
function saveRecord(store,entry){const item=normalizeRecord(store,entry);if(!item)return;if(!idbOk||!dbPromise){persist();return}dbPromise.then(db=>idbPut(db,store,item)).then(()=>recordChannel?.postMessage({type:'records-changed'})).catch(()=>{idbOk=false;persist();notify('数据库写入失败，已改用浏览器本地存储；请导出备份')})}
function deleteRecord(store,id){if(!idbOk||!dbPromise){persist();return}dbPromise.then(db=>idbDelete(db,store,id)).then(()=>recordChannel?.postMessage({type:'records-changed'})).catch(()=>notify('记录删除失败，请重试'))}
async function refreshRecords(){if(!idbOk||!dbPromise)return;try{const db=await dbPromise;const [nextLogs,nextSessions]=await Promise.all([idbGetAll(db,'logs'),idbGetAll(db,'sessions')]);logs=nextLogs.map(x=>normalizeRecord('logs',x)).filter(Boolean);sessions=nextSessions.map(x=>normalizeRecord('sessions',x)).filter(Boolean);renderStats();if(page==='records')renderRecords();if(page==='me')renderMe()}catch(err){console.warn('刷新记录失败，界面保留上一次数据',err)}}
if(recordChannel)recordChannel.onmessage=event=>{if(event.data?.type==='records-changed')refreshRecords()};
function track(kind='pink',level=30,pan=0,freq=4000,bw=1,cutoff=8000){return {id:uid(),kind,level,pan,freq,bw,cutoff,mute:false,solo:false,fileName:''}}
function validTrack(t){const v=sanitizeTrack(t&&typeof t==='object'?t:{});if(!v.id)v.id=uid();if(!TYPES[v.kind])v.kind='pink';return v}
function tracksFor(p){return p.tracks.map(([k,lv,pan,fq,bw,cut])=>track(k,lv,pan,fq,bw,cut))}
const fallback={volume:18,duration:30,fadeIn:5,fadeOut:5,activeName:'轻柔助眠',activeId:'sleep',tracks:tracksFor(PRESETS[0])};
const v4=storage(KEY),v3=storage(OLD_SETTINGS),p3=storage(OLD_PROFILES),l3=storage(OLD_LOGS);
let settings={...fallback,...((v4?.settings||v3)||{})};settings.volume=clamp(settings.volume??18,0,100);if(!v4&&v3)settings.volume=clamp(Math.round(settings.volume*2),0,60);settings.duration=clamp(settings.duration??30,15,90);settings.fadeIn=clamp(settings.fadeIn??settings.fade??5,0,10);settings.fadeOut=clamp(settings.fadeOut??settings.fade??5,0,10);settings.tracks=(Array.isArray(settings.tracks)?settings.tracks:fallback.tracks).slice(0,6).map(validTrack);
let profiles=v4?.profiles&&typeof v4.profiles==='object'?v4.profiles:{};if(!v4&&p3&&typeof p3==='object'){profiles=Object.fromEntries(Object.entries(p3).slice(0,30).map(([name,p])=>[name,{name,createdAt:new Date().toISOString(),settings:{...fallback,...p,tracks:(p.tracks||[]).slice(0,6).map(validTrack)}}]))}
